import os
# Find the repo directory
for root, dirs, files in os.walk('/'):
    if '.git' in dirs and 'boltons' in dirs:
        print(f"Found repo at: {root}")
        break
else:
    # Check common locations
    for p in ['/app', '/workspace', '/home', '/']:
        if os.path.exists(os.path.join(p, '.git')):
            print(f"Found .git at: {p}")
        if os.path.isdir(os.path.join(p, 'repo')):
            print(f"Found repo dir at: {p}/repo")
